import{_ as s,C as n,o as d,c,j as e,a as l,E as i,a3 as o}from"./chunks/framework.D4-ViStF.js";const f=JSON.parse('{"title":"文言传","description":"专释乾坤两卦的传——从元亨利贞与六爻时位，到坤道承载与敬义立身，读懂以传解经的义理样板。","frontmatter":{"title":"文言传","description":"专释乾坤两卦的传——从元亨利贞与六爻时位，到坤道承载与敬义立身，读懂以传解经的义理样板。","category":"guide","aliases":["文言传","文言","wen yan zhuan"],"source":["《周易·文言传》"]},"headers":[],"relativePath":"yijing/shi-yi/wen-yan-zhuan.md","filePath":"yijing/shi-yi/wen-yan-zhuan.md","lastUpdated":1788516578000}'),u={name:"yijing/shi-yi/wen-yan-zhuan.md"};function p(m,a,g,b,q,x){const t=n("DaoReadingPrelude"),r=n("DaoTextReading"),h=n("DaoKeywordCards");return d(),c("div",null,[a[0]||(a[0]=e("h1",{id:"文言传",tabindex:"-1"},[l("文言传 "),e("a",{class:"header-anchor",href:"#文言传","aria-label":'Permalink to "文言传"'},"​")],-1)),i(t,{title:"在每一个位置上，做合乎其时的事",summary:"《文言传》只解释乾、坤两卦，却把两卦的卦辞和爻辞展开成一套完整的修身与处世之学。乾讲创始、刚健、进德与知退；坤讲承载、柔顺、守正与成全。读它，不是只找吉凶，而是看人在不同位置上如何安顿自己。",points:[{label:"先读乾",text:"从元亨利贞与潜龙、见龙、飞龙，理解能力如何随时位展开。"},{label:"再读坤",text:"从至柔、含章、括囊与黄中，理解承载并不等于软弱或失去原则。"},{label:"合读",text:"乾坤不是两种互相排斥的人格，而是创始与完成、主动与承接的两面。"}],hint:"乾、坤都不是鼓励人永远向前或永远退让。真正的关键是：知道自己所处的时、位、势，并在其中做合乎其时的事。"}),a[1]||(a[1]=o('<h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>《文言传》是十翼中唯一专门解释乾、坤两卦的传。它先解释乾卦卦辞「元亨利贞」，再逐一申说乾卦六爻；坤卦则从「坤至柔，而动也刚」开始，展开坤道的承载、守正、含藏与成德。</p><p>它不是简单翻译卦辞，而是示范《易传》如何从一个卦象和一条爻辞中，读出德性、时位、行动和人的修养。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li>乾坤是六十四卦的门户。读懂二者的关系，其余卦的刚柔、时位、进退都有了参照。</li><li>「元亨利贞」被解释为善之长、嘉之会、义之和、事之干，说明卦辞可以展开为可实践的德性。</li><li>乾卦六爻展示一条完整的成长曲线：潜藏、显现、警醒、试跃、当位、过亢。</li><li>坤卦提醒人：柔顺可以有力量，安静可以有边界，不居功也可以把事情完成。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读乾、坤原文，不急着把龙、地、臣、妻等象直接套到现代身份上。</li><li>读乾时抓「时位」：潜、见、乾乾、跃、飞、亢不是简单的等级，而是不同处境下的行动要求。</li><li>读坤时抓「承载与守正」：至柔、含章、括囊、黄中都不是无条件退让。</li><li>将每条爻辞放回卦页，对照卦象、爻位与彖象；再区分经文、传文和现代个人理解。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>乾之四德</strong>：元为善之长，亨为嘉之会，利为义之和，贞为事之干；君子以体仁、合礼、利物、贞固来实践。</li><li><strong>乾之六位</strong>：潜龙勿用、见龙在田、终日乾乾、或跃在渊、飞龙在天、亢龙有悔，写出能力显隐与进退节律。</li><li><strong>乾之大人</strong>：与天地合德、与日月合明、与四时合序，先天而不违、后天而奉时。</li><li><strong>坤之道顺</strong>：坤至柔而动也刚，至静而德方，承天而时行；柔顺不是盲从，而是依规律完成自身工作。</li><li><strong>坤之修身</strong>：履霜知渐，敬以直内、义以方外，含章而不争功，括囊而知谨慎，黄中而发于事业。</li><li><strong>乾坤之极</strong>：亢龙有悔与龙战于野都说明，任何力量走到极端，都会失去原本的秩序。</li></ul><h2 id="与六十四卦的联动" tabindex="-1">与六十四卦的联动 <a class="header-anchor" href="#与六十四卦的联动" aria-label="Permalink to &quot;与六十四卦的联动&quot;">​</a></h2><ul><li>直接对照：<a href="/Dao/yijing/hexagrams/hexagram-01"><code>乾卦</code></a> 与 <a href="/Dao/yijing/hexagrams/hexagram-02"><code>坤卦</code></a> 的卦辞、彖辞、象辞和六爻。</li><li>读其他卦遇到「元亨利贞」时，可回到本文理解四德，而不只把它当成四个吉字。</li><li>「君子终日乾乾」「见几而作」「敬以直内，义以方外」可与<a href="/Dao/yijing/shi-yi/xi-ci-zhuan-xia"><code>系辞下传</code></a>的时位、忧患与行动主题互参。</li><li>「乾坤其《易》之门」也可与<a href="/Dao/yijing/shi-yi/shuo-gua-zhuan"><code>说卦传</code></a>的三才、八卦与取象体系对读。</li></ul><h2 id="【原典层】乾文言" tabindex="-1">【原典层】乾文言 <a class="header-anchor" href="#【原典层】乾文言" aria-label="Permalink to &quot;【原典层】乾文言&quot;">​</a></h2>',12)),i(r,{colophon:"元亨利贞 · 六龙时位 · 大人合天 · 知进知退",tone:"ink",sections:[{id:"qian-01",sentences:[["文言曰：“元者，善之长也；亨者，嘉之会也；利者，义之和也；贞者，事之干也。”"],["君子体仁，足以长人；嘉会，足以合礼；利物，足以和义；贞固，足以干事。君子行此四者，故曰：乾，元亨利贞。"]]},{id:"qian-02",sentences:[["初九曰：“潜龙勿用。”何谓也？子曰：“龙德而隐者也。不易乎世，不成乎名；遁世而无闷，不见是而无闷；乐则行之，忧则违之；确乎其不可拔，乾龙也。”"],["九二曰：“见龙在田，利见大人。”何谓也？子曰：“龙德而正中者也。庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。君德也。”"]]},{id:"qian-03",sentences:[["九三曰：“君子终日乾乾，夕惕若，厉无咎。”何谓也？子曰：“君子进德修业，忠信，所以进德也；修辞立其诚，所以居业也。知至至之，可与几也；知终终之，可与存义也。”"],["是故，居上位而不骄，在下位而不忧。故乾乾，因其时而惕，虽危而无咎矣。"],["九四曰：“或跃在渊，无咎。”何谓也？子曰：“上下无常，非为邪也；进退无恒，非离群也。君子进德修业，欲及时也，故无咎。”"]]},{id:"qian-04",sentences:[["九五曰：“飞龙在天，利见大人。”何谓也？子曰：“同声相应，同气相求；水流湿，火就燥；云从龙，风从虎。圣人作而万物覩，本乎天者亲上，本乎地者亲下，则各从其类也。”"],["上九曰：“亢龙有悔。”何谓也？子曰：“贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。”"]]},{id:"qian-05",sentences:[["乾龙勿用，下也；见龙在田，时舍也；终日乾乾，行事也；或跃在渊，自试也；飞龙在天，上治也；亢龙有悔，穷之灾也；乾元用九，天下治也。"],["乾龙勿用，阳气潜藏；见龙在田，天下文明；终日乾乾，与时偕行；或跃在渊，乾道乃革；飞龙在天，乃位乎天德；亢龙有悔，与时偕极；乾元用九，乃见天则。"]]},{id:"qian-06",sentences:[["乾元者，始而亨者也；利贞者，性情也。乾始能以美利利天下，不言所利。大矣哉！大哉乾乎！刚健中正，纯粹精也。"],["六爻发挥，旁通情也；时乘六龙，以御天也；云行雨施，天下平也。"],["君子以成德为行，日可见之行也。潜之为言也，隐而未见，行而未成，是以君子弗用也。"],["君子学以聚之，问以辩之，宽以居之，仁以行之。见龙在田，利见大人，君德也。"]]},{id:"qian-07",sentences:[["九三，重刚而不中，上不在天，下不在田，故乾乾，因其时而惕，虽危无咎矣。"],["九四，重刚而不中，上不在天，下不在田，中不在人，故或之；或之者，疑之也，故无咎。"],["夫大人者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶。先天下而天弗违，后天而奉天时。"],["亢之为言也，知进而不知退，知存而不知亡，知得而不知丧。其唯圣人乎？知进退存亡，而不失其正者，其为圣人乎！"]]}],"aria-label":"乾文言原文"}),a[2]||(a[2]=e("h2",{id:"【原典层】坤文言",tabindex:"-1"},[l("【原典层】坤文言 "),e("a",{class:"header-anchor",href:"#【原典层】坤文言","aria-label":'Permalink to "【原典层】坤文言"'},"​")],-1)),i(r,{colophon:"至柔动刚 · 承天时行 · 敬直义方 · 黄中通理",tone:"ink",sections:[{id:"kun-01",sentences:[["文言曰：“坤至柔，而动也刚；至静，而德方；后得主而有常；含万物而化光。坤其道顺乎？承天而时行。”"],["积善之家，必有馀庆；积不善之家，必有馀殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辨之不早辨也。履霜坚冰至，盖言顺也。"]]},{id:"kun-02",sentences:[["直其正也，方其义也。君子敬以直内，义以方外，敬义立而德不孤。“直，方，大，不习无不利”，则不疑其所行也。"],["阴虽有美，含之；以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成，而代有终也。"]]},{id:"kun-03",sentences:[["天地变化，草木蕃；天地闭，贤人隐。“括囊；无咎，无誉”，盖言谨也。"],["君子黄中通理，正位居体，美在其中，而畅于四支，发于事业，美之至也。"]]},{id:"kun-04",sentences:[["阴疑于阳，必战。为其嫌于无阳也，故称龙焉；犹未离其类也，故称血焉。夫玄黄者，天地之杂也，天玄而地黄。"]]}],"aria-label":"坤文言原文"}),a[3]||(a[3]=e("blockquote",null,[e("p",null,"注：坤文言中的「妻道」「臣道」属于古代社会的象征与秩序语境，现代阅读不直接将其转化为性别或身份规范。「艮为鼻」等后世取象讨论也应与本文乾坤原典分开，不混同于文言传本身。")],-1)),a[4]||(a[4]=e("h2",{id:"【原典层】字词释义",tabindex:"-1"},[l("【原典层】字词释义 "),e("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(h,{items:[{term:"元亨利贞",pinyin:["yuán","hēng","lì","zhēn"],meaning:"文言分别解释为善之长、嘉之会、义之和、事之干。四字不是四个孤立吉兆，而是一条从发端、通达、合宜到守正的成事结构。"},{term:"体仁",pinyin:["tǐ","rén"],meaning:"以仁为体，把仁落实为自身的行动，因此足以长养、成全他人，而不只是口头谈仁。"},{term:"贞固",pinyin:["zhēn","gù"],meaning:"守住原则与根本。「固」不是僵硬地拒绝变化，而是在方法变化时仍不失诚实、责任与分寸。"},{term:"潜龙",pinyin:["qián","lóng"],meaning:"德性与能力尚在隐伏、行动尚未完成的阶段。勿用不是不学习，而是不把未成熟强行推到台前。"},{term:"见龙",pinyin:["xiàn","lóng"],meaning:"德性开始显现并影响周围。其基础是庸言可信、庸行谨慎、善世而不自伐。"},{term:"知几",pinyin:["zhī","jī"],meaning:"知道事情将动未动的微小征兆。知至至之、知终终之，都是对时机和边界的辨认。"},{term:"大人",pinyin:["dà","rén"],meaning:"不是单指地位高的人，而是能与天地、日月、四时相合，先后皆能奉时而行的德性与担当。"},{term:"至柔动刚",pinyin:["zhì","róu","dòng","gāng"],meaning:"坤外在柔顺，实际行动却有承载和完成的力量。柔并不等于弱，静也不等于没有方向。"},{term:"承天时行",pinyin:["chéng","tiān","shí","xíng"],meaning:"承接规律并依时行动，不是盲从天意，而是看清条件、角色和时势后完成自己的工作。"},{term:"含章",pinyin:["hán","zhāng"],meaning:"内有才华、美德和光明，却不急于显露或争功。含不是压抑才能，而是不让自我证明取代事情本身。"},{term:"括囊",pinyin:["kuò","náng"],meaning:"扎紧袋口，象征天地闭塞或时机不宜时的谨慎收敛；不能把它滥用为逃避应尽责任的借口。"},{term:"黄中通理",pinyin:["huáng","zhōng","tōng","lǐ"],meaning:"内守中正而通达事理，正位居体，内在之美最终流布于言行并落实为事业。"}]}),a[5]||(a[5]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><blockquote><p>这两篇最适合对照阅读：不把乾、坤简化成性格标签，而是观察创始与承载如何在不同位置上互相成就。</p></blockquote><h3 id="象-乾坤两篇在说什么" tabindex="-1">象：乾坤两篇在说什么 <a class="header-anchor" href="#象-乾坤两篇在说什么" aria-label="Permalink to &quot;象：乾坤两篇在说什么&quot;">​</a></h3><p>乾文言把乾卦读成一条君子成长和行动的路径：有能力时先潜藏蓄力，开始显现时以日用诚信立身，处于中段时终日乾乾、进德修业，在跃迁关口先自试、待时，到了高位要使万物有所感应，到了极处则必须知道退。</p><p>坤文言则把坤卦读成一种承事成物的力量：外在柔顺，实际行动刚健；内心安静，却有方正边界；不抢先，却能找到主线和自己的位置；有美而含章，闭塞时知谨慎，内在德性最终畅于四支、发于事业。</p><h3 id="理-为什么乾坤必须合读" tabindex="-1">理：为什么乾坤必须合读 <a class="header-anchor" href="#理-为什么乾坤必须合读" aria-label="Permalink to &quot;理：为什么乾坤必须合读&quot;">​</a></h3><ul><li>乾只讲向上，容易变成逞强；坤只讲顺从，容易变成失去主见。两篇放在一起，才看见主动与承接的完整循环。</li><li>乾的「贞」是做事的骨干，坤的「方」是行动的边界；一个守主干，一个定尺度。</li><li>乾强调「与时偕行」，坤强调「承天时行」；一个是主动随时而进，一个是承接条件而完成。</li><li>乾、坤走到极处都出现警告：亢龙会悔，阴阳疑而战；力量若失去位置，便会从成事转为失序。</li></ul><h3 id="用-今天怎么读自己的位置" tabindex="-1">用：今天怎么读自己的位置 <a class="header-anchor" href="#用-今天怎么读自己的位置" aria-label="Permalink to &quot;用：今天怎么读自己的位置&quot;">​</a></h3><p>可以带着四个问题读乾坤：</p><ul><li>我现在是在潜藏积累、开始显现、过渡试跃，还是已经需要知退？</li><li>我手里是否已有足够的器与能力，还是急着证明自己已经到了「飞龙在天」？</li><li>我是否把柔顺误当成退缩，把谨慎误当成逃避，把不争功误当成不需要维护正当贡献？</li><li>当前最需要的是乾的启动和担当，还是坤的承接、边界、养护与完成？</li></ul><h2 id="【解读层】分段解读" tabindex="-1">【解读层】分段解读 <a class="header-anchor" href="#【解读层】分段解读" aria-label="Permalink to &quot;【解读层】分段解读&quot;">​</a></h2><h3 id="一、乾之四德-元亨利贞是一条成事路径" tabindex="-1">一、乾之四德：元亨利贞是一条成事路径 <a class="header-anchor" href="#一、乾之四德-元亨利贞是一条成事路径" aria-label="Permalink to &quot;一、乾之四德：元亨利贞是一条成事路径&quot;">​</a></h3><p>「元」是善的开端，「亨」是美好事物得以会合，「利」是让事物各得其宜，「贞」是使事情立得住的骨干。它们不是先天保证，而是君子需要逐步实践的四种德性。</p><p>体仁使人能够长养他人，嘉会使人与人合礼，利物使收益不离义，贞固使行动有主干。由此，乾卦的刚健不只是力量和速度，而是有仁、有礼、有利、有守的创始能力。</p><h3 id="二、乾之六龙-位置变化-行动要求随之变化" tabindex="-1">二、乾之六龙：位置变化，行动要求随之变化 <a class="header-anchor" href="#二、乾之六龙-位置变化-行动要求随之变化" aria-label="Permalink to &quot;二、乾之六龙：位置变化，行动要求随之变化&quot;">​</a></h3><p>「潜龙勿用」不是叫人停止，而是提醒尚未显现、尚未完成时，先聚学、聚问、聚诚，不把名声当成果。「见龙在田」则要求把德性落实在庸言庸行，能善世而不伐。</p><p>九三的「终日乾乾」是持续进德修业；九四的「或跃在渊」是处于上下未定的试探关口；九五的「飞龙在天」不是个人独自发光，而是形成感应、使万物得以看见和展开；上九的「亢龙有悔」则警告只知进而不知退。</p><p>乾的六爻不是一条永远向上的成功曲线，而是把「进、退、显、隐、时、位」同时纳入行动判断。</p><h3 id="三、坤之四层-柔顺之中有方向、边界和完成" tabindex="-1">三、坤之四层：柔顺之中有方向、边界和完成 <a class="header-anchor" href="#三、坤之四层-柔顺之中有方向、边界和完成" aria-label="Permalink to &quot;三、坤之四层：柔顺之中有方向、边界和完成&quot;">​</a></h3><p>坤至柔而动也刚，说明承载不是消极承受；至静而德方，说明安静不是没有准则；后得主而有常，说明不争先是先辨主次、找到可依循的方向；含万物而化光，说明坤的工作是让万物得到成长和显明。</p><p>「承天而时行」是坤道的核心：承接不是盲从，顺时也不是随波逐流，而是看清规律、条件与自身位置，再把应做之事完成。</p><h3 id="四、履霜与括囊-从渐变中辨察-在闭塞时知谨慎" tabindex="-1">四、履霜与括囊：从渐变中辨察，在闭塞时知谨慎 <a class="header-anchor" href="#四、履霜与括囊-从渐变中辨察-在闭塞时知谨慎" aria-label="Permalink to &quot;四、履霜与括囊：从渐变中辨察，在闭塞时知谨慎&quot;">​</a></h3><p>「履霜坚冰至」说的是积累与渐变。严重后果常常不是一朝一夕发生，而是小处没有辨明、小错不断放任，终于发展成难以挽回的局面。</p><p>「括囊」则是另一种时位：天地闭塞时，贤人知隐，言行需要收敛。谨慎不是永远沉默，关键要辨认这是为了守护根本，还是为了逃避应承担的责任。</p><h3 id="五、直方大与黄中通理-内在修养最终要发于事业" tabindex="-1">五、直方大与黄中通理：内在修养最终要发于事业 <a class="header-anchor" href="#五、直方大与黄中通理-内在修养最终要发于事业" aria-label="Permalink to &quot;五、直方大与黄中通理：内在修养最终要发于事业&quot;">​</a></h3><p>敬以直内，是如实看见自己的欲望、偏见与不安；义以方外，是让行动有边界、有合宜的尺度。内直外方，德才不会孤立。</p><p>「黄中通理」则把坤德推向完成：内心守中，通达事理，正位居体，内在之美流布到言行，最后发于事业。真正的美不是表面修饰，而是能够长期承事、成事、使他人生长。</p><h3 id="六、乾坤之极-知进退存亡-柔顺而不失其正" tabindex="-1">六、乾坤之极：知进退存亡，柔顺而不失其正 <a class="header-anchor" href="#六、乾坤之极-知进退存亡-柔顺而不失其正" aria-label="Permalink to &quot;六、乾坤之极：知进退存亡，柔顺而不失其正&quot;">​</a></h3><p>乾的极处是亢，坤的极处是战；一个只知道得进而不知退，一个因阴阳相疑而失去各自的位置。二者都提醒我们，任何德性若脱离时位和关系，都会走向反面。</p><p>因此，乾坤合读的落点不是“我应该更强”或“我应该更柔”，而是：该启动时承担，该承接时完成；有力量时不骄，有才能时不伐；环境不宜时知退守，机会来到时也不因恐惧而错过。</p><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>乾像一股向前的力量：它会开始、推进、承担，也会在每个阶段重新判断自己是否合时。它不鼓励永远冲刺，而是要求人在潜藏、显现、试探、当位和极盛之间保持清醒。</p><p>坤像一块能够承事的土地：它不急着争先，却能承接方向；不大声证明，却能把事情养成；不因柔和而放弃边界，也不因不居功而放弃完成。</p><p>一个人真正成熟，也许不是更像乾或更像坤，而是知道什么时候需要哪一种力量：用乾打开局面，用坤让局面落地；用乾守住担当，用坤守住分寸；最后让刚健与柔顺共同服务于一件可以长久的事。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>这次整理留下三点：</p><ul><li>乾坤的重点不在二选一。乾讲主动创始，坤讲承接完成，二者都是完整秩序不可缺少的一面。</li><li>乾的“知进退存亡”，与坤的“承天而时行”都在说明：方法可以变化，但不能失去对时、位、责任和根本的辨认。</li><li>“柔”不等于弱，“不争”也不等于没有价值。只要敬义立、内外有方，安静的承载同样能够产生刚健而持久的结果。</li></ul><h2 id="延伸阅读-参考来源" tabindex="-1">延伸阅读 / 参考来源 <a class="header-anchor" href="#延伸阅读-参考来源" aria-label="Permalink to &quot;延伸阅读 / 参考来源&quot;">​</a></h2><ul><li>十翼总览：<a href="/Dao/yijing/shi-yi/"><code>孔子十翼</code></a></li><li>乾卦：<a href="/Dao/yijing/hexagrams/hexagram-01"><code>文王六十四卦·乾</code></a></li><li>坤卦：<a href="/Dao/yijing/hexagrams/hexagram-02"><code>文王六十四卦·坤</code></a></li><li>相关原典：<a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang"><code>系辞上传</code></a>、<a href="/Dao/yijing/shi-yi/shuo-gua-zhuan"><code>说卦传</code></a></li><li>通行本《周易·文言传》（王弼注、孔颖达疏系统）</li></ul>',39))])}const k=s(u,[["render",p]]);export{f as __pageData,k as default};
